insert into public.dahiras (slug, profile, content, board, quiz) values ('moutahabina', $json${"id":"dahira-moutahabina","slug":"moutahabina","siteUrl":"https://moutahabina.akkili.sn","name":"Dahira Moutahabina Fillahi","shortName":"MOUTAHABINA","nameArabic":"دائرة المتحبن في اللّه","nameMeaning":"ceux qui s'aiment pour Dieu","motto":"S'aimer pour Dieu, servir ensemble.","ringText":"S'AIMER POUR DIEU • SERVIR ENSEMBLE • DEPUIS 1999 •","guideName":"Serigne Mame Malick Sy","guidePhotoUrl":"/assets/tenants/moutahabina/lignee/serigne-mame-malick-sy-portrait.webp","foundedYear":1999,"foundedPlace":"Yeumbeul","membersApprox":150,"logoUrl":"/assets/tenants/moutahabina/logo.webp","logoSmallUrl":"/assets/tenants/moutahabina/logo-128.webp","logoAlt":"Médaillon du dahira avec le portrait de Serigne Mame Malick Sy","theme":{},"contact":{"address":"Yeumbeul, Dakar","phone":"+221 77 440 44 36"},"join":{"mode":"chat","whatsappNumber":"221774404436","prefilledMessage":"Assalamou aleykoum, je souhaite rejoindre le Dahira Moutahabina Fillahi.","callNumber":"+221774404436"},"support":{"text":"Votre soutien finance nos activités et nos actions sociales.","wave":"77 440 44 36","orangeMoney":"77 440 44 36","blessing":"Qu'Allah vous le rende."},"social":[{"platform":"tiktok","url":"https://www.tiktok.com/@dahiramoutahabinafilah0","handle":"@dahiramoutahabinafilah0"}]}$json$::jsonb, $json${"home":{"aboutTitle":"Apprendre, prier et servir, ensemble.","aboutText":"Né à Yeumbeul en 1999 sous la guidance de Serigne Mansour Sy « Borom Daaraji », le dahira est guidé depuis 2012 par son fils, Serigne Mame Malick Sy."},"about":{"heroTitle":"Une famille née à Yeumbeul en 1999.","history":[{"year":"1999","title":"Naissance à Yeumbeul","text":"Des fidèles de Yeumbeul fondent le dahira sous la guidance de Serigne Mansour Sy « Borom Daaraji »."},{"year":"2012","title":"Une guidance qui continue","text":"Après le rappel à Dieu de Serigne Mansour Sy, le dahira poursuit son chemin avec son fils, Serigne Mame Malick Sy."},{"year":"Aujourd'hui","title":"Une grande famille","text":"Près de 150 membres, à Yeumbeul, à Dakar et dans la diaspora, réunis pour apprendre, prier et servir.","highlight":true}]},"guide":{"intro":"Fils de Serigne Mansour Sy « Borom Daaraji », il guide le dahira depuis 2012, à la suite de son père qui l'accompagnait depuis sa fondation en 1999.","bio":"[Présentation de Serigne Mame Malick Sy : parcours, enseignement, lien avec le dahira. À rédiger et valider par le bureau.]","lineageTitle":"Quatre générations au service du savoir","lineageIntro":"De Gaya à Tivaouane, puis jusqu'à notre dahira : une même école, celle de Seydi El Hadji Malick Sy, transmise de père en fils.","lineage":[{"relation":"Arrière-grand-père","name":"Seydi El Hadji Malick Sy","alias":"Maodo","years":"† 27 juin 1922","text":"Né à Gaya, dans le Walo, il étudie en Mauritanie puis à Saint-Louis. Installé à Tivaouane au début du XXᵉ siècle, il y fonde la zawiya et une grande école d'où sortent de nombreux muqaddams de la Tijaniyya.","photoUrl":"/assets/tenants/moutahabina/lignee/seydi-el-hadji-malick-sy.webp","milestones":[{"year":"1884","label":"Études à Saint-Louis"},{"year":"Vers 1902","label":"Installation à Tivaouane"},{"year":"1922","label":"Rappel à Dieu, le 27 juin"}]},{"relation":"Grand-père","name":"Serigne Babacar Sy","alias":"Borom bonnet carré","years":"1885 – 1957","text":"Fils aîné de Maodo et de Sokhna Rokhaya Ndiaye, né à Saint-Louis. Devenu à 37 ans le premier Khalife général des Tidianes, il initie les dahiras, comme la Dahiratoul Kiram, qui structurent la communauté autour de l'entraide et de l'enseignement.","photoUrl":"/assets/tenants/moutahabina/lignee/serigne-babacar-sy.webp","milestones":[{"year":"1885","label":"Naissance à Saint-Louis"},{"year":"1922","label":"Premier Khalife général des Tidianes"},{"year":"1957","label":"Rappel à Dieu, le 25 mars, à Tivaouane"}]},{"relation":"Père","name":"Serigne Mansour Sy","alias":"Borom Daaraji","years":"1925 – 2012","text":"Fils de Serigne Babacar Sy et de Sokhna Aïssatou Seck. Il dirige pendant de longues années le grand daara fondé par son grand-père, d'où son surnom. Khalife général des Tidianes, il guide notre dahira dès sa fondation en 1999.","photoUrl":"/assets/tenants/moutahabina/lignee/serigne-mansour-sy.webp","milestones":[{"year":"1925","label":"Naissance à Tivaouane, le 15 août"},{"year":"1997","label":"Khalife général des Tidianes"},{"year":"1999","label":"Guide du dahira dès sa fondation"},{"year":"2012","label":"Rappel à Dieu, le 9 décembre"}]},{"relation":"Notre guide","name":"Serigne Mame Malick Sy","text":"Fils de Serigne Mansour Sy, il guide le dahira depuis 2012. [Parcours et enseignement : à fournir par le bureau.]","highlight":true,"photoUrl":"/assets/tenants/moutahabina/lignee/serigne-mame-malick-sy.webp","milestones":[{"year":"2012","label":"Guide du dahira"}]}],"didYouKnow":"Les premiers dahiras ont été initiés par Serigne Babacar Sy. Ils sont devenus des piliers de solidarité et d'éducation.","sources":"Textes établis d'après la presse sénégalaise. À faire relire et valider par le bureau.","sourceLinks":[{"label":"Le Soleil — Serigne Babacar Sy, « Borom bonnet carré »","url":"https://lesoleil.sn/actualites/societe-fait-divers/religion/serigne-babacar-sy-borom-bonnet-carre-le-batisseur-de-la-tidianiyya-moderne/"},{"label":"Le Soleil — Serigne Mansour Sy « Borom Daraadji »","url":"https://lesoleil.sn/actualites/serigne-mansour-sy-borom-daraadji-le-grand-savant-pedagogue/"},{"label":"Senego — La vie et l'œuvre de Seydi El Hadji Malick Sy","url":"https://senego.com/la-vie-et-loeuvre-de-seydil-hadj-malick-sy-passee-au-peigne-fin_599663.html"},{"label":"Senego — La Dahiratoul Kiram","url":"https://senego.com/serigne-babacar-sy-la-dahiratoul-kiram-socle-de-la-structuration-tidiane_1996849.html"}]},"join":{"intro":"Pas de formulaire. Un message sur WhatsApp, et un responsable vous répond.","steps":["Vous appuyez sur « Rejoindre sur WhatsApp ».","Vous envoyez le message déjà écrit.","Un responsable vous répond et vous ajoute au groupe du dahira."]},"charter":{"intro":"Les règles de vie du dahira, pour les nouveaux comme pour les anciens membres.","rules":[{"title":"Avoir une carte de membre"},{"title":"Moutahabina Fillahi","wolof":"Sopanté té Yalla takh","detail":"S'aimer pour Dieu."},{"title":"Discipline","wolof":"Yar ak téguine"},{"title":"Présence physique et financière","wolof":"Téw tay téwal"},{"title":"Tenue blanche obligatoire","detail":"Ou, à défaut, une tenue correcte."},{"title":"Baptême ou mariage","detail":"Chaque membre cotise.","amounts":[{"label":"Par membre","amount":"1 000 F CFA"}]},{"title":"Le jour de son dahira","detail":"Chaque membre donne 4 000 F CFA le jour où il reçoit le dahira.","amounts":[{"label":"Sonorisation","amount":"2 000 F CFA"},{"label":"Thé (ataya)","amount":"2 000 F CFA"}]}],"schedule":[{"time":"21 h 00","label":"Début du dahira"},{"time":"21 h 00 – 22 h 40","label":"Nabiens"},{"time":"22 h 40 – 23 h 20","label":"Oustaz"},{"time":"23 h 20","label":"Informations"},{"time":"23 h 30","label":"Fin du dahira"}],"scheduleNote":"Le dahira commence à 21 h 00 et se termine à 23 h 30."}}$json$::jsonb, $json${"people":[{"id":"p01","name":"Seydi Djamil Fall"},{"id":"p02","name":"Aminata Ndiaye"},{"id":"p03","name":"Lamine Dièmè"},{"id":"p04","name":"Ndeye Coure Gueye"},{"id":"p05","name":"Baye Moussa Niang"},{"id":"p06","name":"Souleymane Kandé"},{"id":"p07","name":"Sophia Kandé"},{"id":"p08","name":"Khoudia Diouf"},{"id":"p09","name":"Mouhamed Fall"},{"id":"p10","name":"Bada Sarr"},{"id":"p11","name":"Mandou Konaté"},{"id":"p12","name":"Astou Mbène Faye"},{"id":"p13","name":"Mouhaned Diatta"},{"id":"p14","name":"Hawa Touré"},{"id":"p15","name":"Mbarka Ndiaye"},{"id":"p16","name":"Djamile Niang"},{"id":"p17","name":"Aïda Mbaye Niang"},{"id":"p18","name":"Diarry Diémé"},{"id":"p19","name":"Papa Seydou Ndiaye"},{"id":"p20","name":"Idrissa Fall"},{"id":"p21","name":"Satou Coly"},{"id":"p22","name":"Coumbis Siby"},{"id":"p23","name":"Oustaz Issa Coly"},{"id":"p24","name":"Aboubacar Ndiaye"},{"id":"p25","name":"Ousmane Diallo"},{"id":"p26","name":"Issa Sagna"},{"id":"p27","name":"Marème Mbaye"},{"id":"p28","name":"Abdou Diouf"},{"id":"p29","name":"Oustaz Cheikh Tidiane Tamboura"},{"id":"p30","name":"Oustaz Abdou Rahmane Diop"}],"executive":[{"personId":"p01","role":"Président"},{"personId":"p02","role":"Présidente"},{"personId":"p05","role":"Secrétaire général"},{"personId":"p09","role":"Trésorier"}],"commissions":[{"id":"vice-presidence","name":"Vice-présidence","members":[{"personId":"p03","role":"Vice-président(e)"},{"personId":"p04","role":"Vice-président(e)"}]},{"id":"secretariat","name":"Secrétariat général","members":[{"personId":"p05","role":"Secrétaire général","lead":true},{"personId":"p06"},{"personId":"p07"},{"personId":"p08"}]},{"id":"tresorerie","name":"Trésorerie","description":"Tient les finances du dahira.","members":[{"personId":"p09","role":"Trésorier","lead":true},{"personId":"p10","role":"Trésorier adjoint"}]},{"id":"organisation","name":"Organisation","description":"Prépare les dahiras, l'accueil et les déplacements.","members":[{"personId":"p11","role":"Président(e) organisation","lead":true},{"personId":"p12","role":"Président(e) organisation"},{"personId":"p13","role":"Vice-président(e) organisation"},{"personId":"p14","role":"Vice-président(e) organisation"}]},{"id":"coordination","name":"Coordination","members":[{"personId":"p15"},{"personId":"p16"},{"personId":"p17"},{"personId":"p18"}]},{"id":"commissaires-aux-comptes","name":"Commissaires aux comptes","description":"Contrôlent les comptes du dahira.","members":[{"personId":"p19"},{"personId":"p20"},{"personId":"p21"},{"personId":"p22"}]},{"id":"social","name":"Social","description":"Accompagne les membres lors des baptêmes, mariages, maladies et deuils.","members":[{"personId":"p23"},{"personId":"p24"},{"personId":"p25"},{"personId":"p26"},{"personId":"p27"}]},{"id":"micro-centrale-des-nabiens","name":"Micro centrale des nabiens","members":[{"personId":"p28"}]},{"id":"commission-scientifique","name":"Commission scientifique","members":[{"personId":"p23"},{"personId":"p29"},{"personId":"p30"}]},{"id":"sonorisation","name":"Sonorisation","description":"Installe et gère le son pendant les dahiras.","members":[{"personId":"p05"},{"personId":"p20"},{"personId":"p06"}]}]}$json$::jsonb, $json${"intro":"Apprenez en jouant : les ablutions, la prière, le dahira et sa charte. Sans inscription : jouez, apprenez, partagez votre score.","themes":[{"id":"farata-ndiapp","title":"Farata ndiapp","description":"Les obligations des ablutions.","icon":"ph-drop","source":"Mukhtasar d'Al-Akhdari (rite malikite)","questions":[{"question":"Combien y a-t-il de farata dans les ablutions ?","choices":["7","5","10"],"answer":0,"explanation":"Les obligations des ablutions sont au nombre de sept.","ar":{"question":"كم عدد فرائض الوضوء؟","choices":["سبع","خمس","عشر"],"explanation":"فرائض الوضوء سبع."}},{"question":"Quelle est la première farata des ablutions ?","choices":["L'intention (niyya)","Se rincer la bouche","Se laver les oreilles"],"answer":0,"explanation":"La première obligation est l'intention, faite au début des ablutions.","ar":{"question":"ما أول فرائض الوضوء؟","choices":["النية","المضمضة","مسح الأذنين"],"explanation":"أول فرائض الوضوء النية، تكون عند الشروع فيه."}},{"question":"Jusqu'où faut-il laver les bras ?","choices":["Jusqu'aux coudes","Jusqu'aux poignets","Jusqu'aux épaules"],"answer":0,"explanation":"On lave les bras jusqu'aux coudes.","ar":{"question":"إلى أين تُغسل اليدان؟","choices":["إلى المرفقين","إلى الكوعين","إلى المنكبين"],"explanation":"من فرائض الوضوء غسل اليدين إلى المرفقين."},"choiceImages":["/assets/quiz/ablution-bras-coudes.svg","/assets/quiz/ablution-mains-poignets.svg","/assets/quiz/ablution-bras-epaules.svg"]},{"question":"Pour la tête, que faut-il faire ?","choices":["Passer les mains mouillées dessus (massah)","La laver entièrement","Rien"],"answer":0,"explanation":"On passe les mains mouillées sur la tête : c'est le massah.","ar":{"question":"ماذا يُفعل بالرأس في الوضوء؟","choices":["يُمسح باليدين المبلولتين","يُغسل كله","لا شيء"],"explanation":"من فرائض الوضوء مسح الرأس."},"image":"/assets/quiz/ablution-tete.svg","imageAlt":"Les mains mouillées passent sur la tête"},{"question":"Jusqu'où faut-il laver les pieds ?","choices":["Jusqu'aux chevilles","Jusqu'aux genoux","Seulement les orteils"],"answer":0,"explanation":"On lave les pieds jusqu'aux chevilles.","ar":{"question":"إلى أين تُغسل الرجلان؟","choices":["إلى الكعبين","إلى الركبتين","الأصابع فقط"],"explanation":"من فرائض الوضوء غسل الرجلين إلى الكعبين."},"choiceImages":["/assets/quiz/ablution-pieds-chevilles.svg","/assets/quiz/ablution-pieds-genoux.svg","/assets/quiz/ablution-orteils.svg"]},{"question":"Que veut dire « dalk » ?","choices":["Frotter les membres en les lavant","Laver trois fois","Commencer par la droite"],"answer":0,"explanation":"Le dalk, c'est frotter chaque membre en le lavant. C'est une obligation.","ar":{"question":"ما هو الدلك؟","choices":["إمرار اليد على العضو مع الغسل","الغسل ثلاث مرات","البداية باليمنى"],"explanation":"الدلك من فرائض الوضوء."}},{"question":"Que veut dire « fawr » ?","choices":["Enchaîner les ablutions sans s'arrêter longtemps","Faire très vite","Utiliser beaucoup d'eau"],"answer":0,"explanation":"Le fawr, c'est enchaîner les ablutions sans longue interruption.","ar":{"question":"ما هو الفور؟","choices":["الموالاة بين الأعضاء دون تفريق طويل","الإسراع الشديد","كثرة الماء"],"explanation":"الفور من فرائض الوضوء."}},{"question":"On a oublié une farata et on s'en souvient tout de suite. Que faire ?","choices":["La faire, puis ce qui vient après","Ne rien faire","Attendre la prochaine prière"],"answer":0,"explanation":"Si l'on s'en souvient vite, on fait l'obligation oubliée, puis ce qui vient après.","ar":{"question":"من نسي فرضا من أعضائه وتذكره بالقرب، ماذا يفعل؟","choices":["يفعله ويفعل ما بعده","لا شيء عليه","ينتظر الصلاة القادمة"],"explanation":"من نسي فرضا فإن تذكره بالقرب فعله وما بعده."}}],"ar":{"title":"فرائض الوضوء","description":"فرائض الوضوء السبع."}},{"id":"sunna-ndiapp","title":"Sunna ndiapp","description":"Farata ou sunna ? Ce qui est recommandé dans les ablutions.","icon":"ph-drop-half","source":"Mukhtasar d'Al-Akhdari (rite malikite)","keepOrder":true,"questions":[{"question":"Se rincer la bouche (madmada)","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"Se rincer la bouche est une sunna des ablutions.","ar":{"question":"المضمضة","choices":["فرض","سنة"],"explanation":"المضمضة من سنن الوضوء."},"image":"/assets/quiz/ablution-bouche.svg","imageAlt":"Se rincer la bouche"},{"question":"Aspirer l'eau par le nez (istinchâq)","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"Aspirer l'eau par le nez est une sunna.","ar":{"question":"الاستنشاق","choices":["فرض","سنة"],"explanation":"الاستنشاق من سنن الوضوء."},"image":"/assets/quiz/ablution-nez.svg","imageAlt":"Aspirer l’eau par le nez"},{"question":"Laver le visage","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":0,"explanation":"Laver le visage est une farata.","ar":{"question":"غسل الوجه","choices":["فرض","سنة"],"explanation":"غسل الوجه من فرائض الوضوء."},"image":"/assets/quiz/ablution-visage.svg","imageAlt":"Laver le visage"},{"question":"Essuyer les oreilles","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"Essuyer les oreilles est une sunna, en reprenant de l'eau pour elles.","ar":{"question":"مسح الأذنين","choices":["فرض","سنة"],"explanation":"مسح الأذنين وتجديد الماء لهما من سنن الوضوء."},"image":"/assets/quiz/ablution-oreilles.svg","imageAlt":"Essuyer les oreilles"},{"question":"Se laver les mains jusqu'aux poignets au début","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"Se laver les mains jusqu'aux poignets en commençant est une sunna.","ar":{"question":"غسل اليدين إلى الكوعين عند الشروع","choices":["فرض","سنة"],"explanation":"غسل اليدين إلى الكوعين عند الشروع من سنن الوضوء."},"image":"/assets/quiz/ablution-mains-poignets.svg","imageAlt":"Laver les mains jusqu’aux poignets"},{"question":"Frotter les membres (dalk)","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":0,"explanation":"Le dalk est une farata.","ar":{"question":"الدلك","choices":["فرض","سنة"],"explanation":"الدلك من فرائض الوضوء."}},{"question":"Respecter l'ordre des farata","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"Respecter l'ordre entre les obligations est une sunna.","ar":{"question":"الترتيب بين الفرائض","choices":["فرض","سنة"],"explanation":"الترتيب بين الفرائض من سنن الوضوء."}},{"question":"On a oublié une sunna des ablutions. Que faire ?","choices":["La faire, sans refaire la prière","Refaire toutes ses prières","Recommencer les ablutions et la prière"],"answer":0,"explanation":"Si l'on oublie une sunna, on la fait, et on ne refait pas la prière.","ar":{"question":"من ترك سنة من سنن الوضوء، ماذا يفعل؟","choices":["يفعلها ولا يعيد الصلاة","يعيد كل صلواته","يعيد الوضوء والصلاة"],"explanation":"وإن ترك سنة فعلها ولا يعيد الصلاة."}}],"ar":{"title":"سنن الوضوء","description":"فرض أم سنة؟ سنن الوضوء."}},{"id":"farata-diouli","title":"Farata diouli","description":"Les obligations de la prière.","icon":"ph-hands-praying","source":"Mukhtasar d'Al-Akhdari (rite malikite)","questions":[{"question":"Combien y a-t-il de farata dans la prière ?","choices":["14","7","5"],"answer":0,"explanation":"Al-Akhdari en cite quatorze.","ar":{"question":"كم عدد فرائض الصلاة عند الأخضري؟","choices":["أربع عشرة","سبع","خمس"],"explanation":"ذكر الأخضري أربع عشرة فريضة."}},{"question":"Par quoi entre-t-on en prière ?","choices":["La takbîr d'entrée « Allahou Akbar »","Le salam","Une sourate"],"answer":0,"explanation":"On entre en prière par la takbîr d'entrée (takbîratoul ihrâm), dite debout.","ar":{"question":"بمَ يدخل المصلي في الصلاة؟","choices":["بتكبيرة الإحرام","بالسلام","بالسورة"],"explanation":"من فرائض الصلاة تكبيرة الإحرام والقيام لها."},"image":"/assets/quiz/priere-takbir.svg","imageAlt":"Takbîr d’entrée, mains levées"},{"question":"Quand faut-il faire l'intention de la prière ?","choices":["Au moment de la takbîr d'entrée","Après la Fâtiha","À la fin de la prière"],"answer":0,"explanation":"L'intention doit accompagner la takbîr d'entrée.","ar":{"question":"متى تكون نية الصلاة؟","choices":["مقارنة لتكبيرة الإحرام","بعد الفاتحة","في آخر الصلاة"],"explanation":"وشروط النية مقارنتها لتكبيرة الإحرام."}},{"question":"Réciter la Fâtiha","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":0,"explanation":"Réciter la Fâtiha, debout, est une farata.","ar":{"question":"قراءة الفاتحة","choices":["فرض","سنة"],"explanation":"الفاتحة والقيام لها من فرائض الصلاة."},"image":"/assets/quiz/priere-debout.svg","imageAlt":"Debout pour réciter la Fâtiha"},{"question":"Se redresser après l'inclinaison (roukou')","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":0,"explanation":"L'inclinaison et le redressement sont des farata.","ar":{"question":"الرفع من الركوع","choices":["فرض","سنة"],"explanation":"الركوع والرفع منه من فرائض الصلاة."},"image":"/assets/quiz/priere-roukou.svg","imageAlt":"Inclinaison (roukou’)"},{"question":"Que veut dire « touma'nîna » ?","choices":["Marquer un temps de calme dans chaque position","Prier vite","Prier à voix haute"],"answer":0,"explanation":"La touma'nîna, c'est rester calme un instant dans chaque position. C'est une farata.","ar":{"question":"ما هي الطمأنينة؟","choices":["السكون في كل ركن قليلا","الإسراع في الصلاة","الجهر بالقراءة"],"explanation":"الطمأنينة من فرائض الصلاة."}},{"question":"Poser le front au sol pendant la prosternation","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":0,"explanation":"La prosternation sur le front est une farata.","ar":{"question":"السجود على الجبهة","choices":["فرض","سنة"],"explanation":"السجود على الجبهة والرفع منه من فرائض الصلاة."},"image":"/assets/quiz/priere-soujoud.svg","imageAlt":"Prosternation, le front au sol"},{"question":"Comment sort-on de la prière ?","choices":["Par le salam, en étant assis","Par la takbîr","En se levant"],"answer":0,"explanation":"Le salam, et la position assise qui l'accompagne, sont des farata.","ar":{"question":"بمَ يخرج المصلي من الصلاة؟","choices":["بالسلام مع الجلوس له","بالتكبير","بالقيام"],"explanation":"السلام وجلوسه الذي يقارنه من فرائض الصلاة."},"image":"/assets/quiz/priere-salam.svg","imageAlt":"Salam, en position assise"}],"ar":{"title":"فرائض الصلاة","description":"فرائض الصلاة."}},{"id":"sunna-diouli","title":"Sunna diouli","description":"Farata ou sunna ? Ce qui est recommandé dans la prière.","icon":"ph-mosque","source":"Mukhtasar d'Al-Akhdari (rite malikite)","keepOrder":true,"questions":[{"question":"Réciter une sourate après la Fâtiha","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"La sourate après la Fâtiha est une sunna.","ar":{"question":"السورة التي بعد الفاتحة","choices":["فرض","سنة"],"explanation":"السورة التي بعد الفاتحة من سنن الصلاة."},"image":"/assets/quiz/priere-debout.svg","imageAlt":"Debout pour réciter la sourate"},{"question":"Les « Allahou Akbar » après celui d'entrée","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"Toutes les takbîr sont des sunnas, sauf la première.","ar":{"question":"التكبير بعد تكبيرة الإحرام","choices":["فرض","سنة"],"explanation":"كل تكبيرة سنة إلا الأولى."}},{"question":"Dire « Sami'allâhou liman hamidah »","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"C'est une sunna.","ar":{"question":"قول: سمع الله لمن حمده","choices":["فرض","سنة"],"explanation":"سمع الله لمن حمده من سنن الصلاة."}},{"question":"Le tachahhoud (attahiyyâtou)","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"Les deux tachahhoud, et la position assise pour eux, sont des sunnas.","ar":{"question":"التشهد","choices":["فرض","سنة"],"explanation":"التشهدان والجلوس لهما من سنن الصلاة."},"image":"/assets/quiz/priere-assis.svg","imageAlt":"Assis pour le tachahhoud"},{"question":"La takbîr d'entrée « Allahou Akbar »","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":0,"explanation":"La takbîr d'entrée est une farata.","ar":{"question":"تكبيرة الإحرام","choices":["فرض","سنة"],"explanation":"تكبيرة الإحرام من فرائض الصلاة."},"image":"/assets/quiz/priere-takbir.svg","imageAlt":"Takbîr d’entrée, mains levées"},{"question":"La prière sur le Prophète (PSL)","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"La prière sur le Prophète (PSL) est une sunna.","ar":{"question":"الصلاة على رسول الله ﷺ","choices":["فرض","سنة"],"explanation":"الصلاة على رسول الله ﷺ من سنن الصلاة."}},{"question":"L'iqâma avant la prière","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"L'iqâma est une sunna.","ar":{"question":"الإقامة","choices":["فرض","سنة"],"explanation":"الإقامة من سنن الصلاة."}},{"question":"Réciter à voix haute dans les prières à voix haute","choices":["Farata (obligatoire)","Sunna (recommandée)"],"answer":1,"explanation":"Réciter à voix haute là où c'est prévu est une sunna.","ar":{"question":"الجهر فيما يجهر فيه","choices":["فرض","سنة"],"explanation":"الجهر فيما يجهر فيه من سنن الصلاة."}}],"ar":{"title":"سنن الصلاة","description":"فرض أم سنة؟ سنن الصلاة."}},{"id":"notre-dahira","title":"Notre dahira","description":"Son histoire, son nom et son guide.","icon":"ph-users-three","questions":[{"question":"En quelle année le dahira a-t-il été fondé ?","choices":["1999","2012","1985"],"answer":0,"explanation":"Le dahira est né à Yeumbeul en 1999."},{"question":"Dans quelle localité le dahira est-il né ?","choices":["Yeumbeul","Tivaouane","Saint-Louis"],"answer":0,"explanation":"Des fidèles de Yeumbeul ont fondé le dahira en 1999."},{"question":"Que signifie « Moutahabina Fillahi » ?","choices":["Ceux qui s'aiment pour Dieu","Ceux qui voyagent pour Dieu","Les gardiens du savoir"],"answer":0,"explanation":"Moutahabina Fillahi : « ceux qui s'aiment pour Dieu »."},{"question":"Sous la guidance de qui le dahira a-t-il été fondé ?","choices":["Serigne Mansour Sy « Borom Daaraji »","Serigne Babacar Sy","Seydi El Hadji Malick Sy"],"answer":0,"explanation":"Serigne Mansour Sy « Borom Daaraji » guidait le dahira dès sa fondation en 1999.","choiceImages":["/assets/tenants/moutahabina/lignee/serigne-mansour-sy.webp","/assets/tenants/moutahabina/lignee/serigne-babacar-sy.webp","/assets/tenants/moutahabina/lignee/seydi-el-hadji-malick-sy.webp"]},{"question":"Depuis quelle année Serigne Mame Malick Sy guide-t-il le dahira ?","choices":["2012","1999","2020"],"answer":0,"explanation":"Après le rappel à Dieu de Serigne Mansour Sy en 2012, son fils Serigne Mame Malick Sy guide le dahira.","image":"/assets/tenants/moutahabina/lignee/serigne-mame-malick-sy.webp","imageAlt":"Portrait de Serigne Mame Malick Sy"},{"question":"Quelle est la devise du dahira ?","choices":["S'aimer pour Dieu, servir ensemble.","Apprendre avant de parler.","Le travail avant tout."],"answer":0,"explanation":"« S'aimer pour Dieu, servir ensemble » : c'est le sens même de Moutahabina Fillahi."}]},{"id":"lignee-de-tivaouane","title":"La lignée de Tivaouane","description":"Quatre générations au service du savoir.","icon":"ph-book-open-text","questions":[{"question":"Quel surnom donne-t-on à Seydi El Hadji Malick Sy ?","choices":["Maodo","Borom Daaraji","Borom bonnet carré"],"answer":0,"explanation":"Seydi El Hadji Malick Sy est appelé « Maodo ».","image":"/assets/tenants/moutahabina/lignee/seydi-el-hadji-malick-sy.webp","imageAlt":"Portrait de Seydi El Hadji Malick Sy"},{"question":"Dans quelle ville Seydi El Hadji Malick Sy s'installe-t-il au début du XXᵉ siècle pour y fonder sa grande école ?","choices":["Tivaouane","Kaolack","Ziguinchor"],"answer":0,"explanation":"Installé à Tivaouane, il y fonde la zawiya et une grande école d'où sortent de nombreux muqaddams."},{"question":"En quelle année Seydi El Hadji Malick Sy est-il rappelé à Dieu ?","choices":["1922","1957","1902"],"answer":0,"explanation":"Il est rappelé à Dieu le 27 juin 1922."},{"question":"Qui fut le premier Khalife général des Tidianes ?","choices":["Serigne Babacar Sy","Serigne Mansour Sy","Serigne Mame Malick Sy"],"answer":0,"explanation":"Serigne Babacar Sy devient le premier Khalife général des Tidianes en 1922, à 37 ans.","choiceImages":["/assets/tenants/moutahabina/lignee/serigne-babacar-sy.webp","/assets/tenants/moutahabina/lignee/serigne-mansour-sy.webp","/assets/tenants/moutahabina/lignee/serigne-mame-malick-sy.webp"]},{"question":"Quel surnom porte Serigne Babacar Sy ?","choices":["Borom bonnet carré","Maodo","Borom Daaraji"],"answer":0,"explanation":"Serigne Babacar Sy est appelé « Borom bonnet carré ».","image":"/assets/tenants/moutahabina/lignee/serigne-babacar-sy.webp","imageAlt":"Portrait de Serigne Babacar Sy"},{"question":"Quel rôle Serigne Babacar Sy a-t-il joué pour les dahiras ?","choices":["Il a initié les premiers dahiras","Il a interdit les dahiras","Aucun rôle particulier"],"answer":0,"explanation":"Il initie les dahiras, comme la Dahiratoul Kiram, piliers d'entraide et d'enseignement."},{"question":"Pourquoi Serigne Mansour Sy est-il appelé « Borom Daaraji » ?","choices":["Il a dirigé le grand daara fondé par son grand-père","C'est le nom de son village natal","C'est le nom de son premier livre"],"answer":0,"explanation":"Pendant de longues années, il a dirigé le grand daara de Tivaouane fondé par Maodo.","image":"/assets/tenants/moutahabina/lignee/serigne-mansour-sy.webp","imageAlt":"Portrait de Serigne Mansour Sy"},{"question":"Qui est le père de notre guide, Serigne Mame Malick Sy ?","choices":["Serigne Mansour Sy","Serigne Babacar Sy","Seydi El Hadji Malick Sy"],"answer":0,"explanation":"Serigne Mame Malick Sy est le fils de Serigne Mansour Sy « Borom Daaraji ».","choiceImages":["/assets/tenants/moutahabina/lignee/serigne-mansour-sy.webp","/assets/tenants/moutahabina/lignee/serigne-babacar-sy.webp","/assets/tenants/moutahabina/lignee/seydi-el-hadji-malick-sy.webp"]}]},{"id":"notre-charte","title":"Notre charte","description":"Les engagements des membres et le déroulement d'un dahira.","icon":"ph-scroll","questions":[{"question":"Quelle tenue est obligatoire au dahira ?","choices":["La tenue blanche (ou une tenue correcte)","Une tenue verte","Aucune tenue particulière"],"answer":0,"explanation":"La charte demande une tenue blanche, ou à défaut une tenue correcte."},{"question":"À quelle heure commence le dahira ?","choices":["21 h 00","20 h 00","22 h 40"],"answer":0,"explanation":"Le dahira commence à 21 h 00 et se termine à 23 h 30."},{"question":"Que se passe-t-il de 22 h 40 à 23 h 20 ?","choices":["L'Oustaz","Les nabiens","Les informations"],"answer":0,"explanation":"Nabiens de 21 h 00 à 22 h 40, puis l'Oustaz de 22 h 40 à 23 h 20, et les informations à 23 h 20."},{"question":"Combien chaque membre cotise-t-il pour un baptême ou un mariage ?","choices":["1 000 F CFA","2 000 F CFA","4 000 F CFA"],"answer":0,"explanation":"Pour un baptême ou un mariage, chaque membre cotise 1 000 F CFA."},{"question":"Combien un membre donne-t-il le jour où il reçoit le dahira ?","choices":["4 000 F CFA","1 000 F CFA","2 000 F CFA"],"answer":0,"explanation":"4 000 F CFA : 2 000 pour la sonorisation et 2 000 pour le thé (ataya)."},{"question":"Que veut dire « Yar ak téguine » ?","choices":["La discipline","La présence","La tenue correcte"],"answer":0,"explanation":"« Yar ak téguine » : la discipline, l'un des engagements de la charte."},{"question":"À quoi correspond « Téw tay téwal » ?","choices":["La présence physique et financière","La discipline","La carte de membre"],"answer":0,"explanation":"« Téw tay téwal » : être présent, physiquement et financièrement."}]}]}$json$::jsonb);
